from pathlib import Path
import json,hashlib,time,subprocess,sys
import run
H=Path(__file__).resolve().parent;E=H/'evidence';ROOT=run.ROOT
while not (E/'boundary_format_002.json').exists():time.sleep(10)
mandatory=['final_check_001','final_authoring_001','final_value_expr_001','final_event_check_001','final_release_001','boundary_all_002','boundary_feature_002','boundary_clippy_002','boundary_list_002','boundary_format_002','finite_workload_002','cli_finish_005','cli_aggregate_002','pc_boundary_002']
current=run.identity(); now={n:(b,h) for n,b,h in current['files']};proof=[]
for name in mandatory:
 d=json.loads((E/(name+'.json')).read_text());assert d['exit_code']==0,name;assert d['source_before']==d['source_after'],name
 then={n:(b,h) for n,b,h in d['source_after']['files']};delta=[n for n in sorted(then.keys()|now.keys()) if then.get(n)!=now.get(n)]
 allowed={'core_enhanced/src/game/battle/core/tests/amount_order.rs','core_enhanced/docs/core_runtime_contract.md','core_enhanced/docs/skill_target_contract.md','core_enhanced/docs/game_rulebook.md','core_enhanced/docs/goals/content_authoring_value_expressions_reassessment/execution/single_goal/evidence/preimplementation/active_run_v7.pre_r06.json'}
 assert set(delta)<=allowed,(name,delta)
 proof.append({'receipt':name+'.json','exit':0,'passed':d['test_passed'],'source_delta':delta,'reuse_basis':'exact current' if not delta else 'only docs/new focused test and previously existing raw fixture membership; product runtime/data/config/lock byte-identical'})
assert json.loads((E/'PC_SUMMARY.json').read_text())['same_gameplay_oracle_and_typed_refusal']
r05=json.loads((E/'R05_SUMMARY.json').read_text());assert not r05['other_hard_guard_failures']
with (E/'VALIDATION_CURRENTNESS.json').open('x') as f:json.dump({'current':current['digest'],'receipts':proof,'R05':r05['classification'],'independent_audit':'not performed'},f,indent=2)
coverage=json.loads((H/'COVERAGE.json').read_text())
for row in coverage['integration']:
 row['result']='passed_self_validation';row['receipt']='evidence/boundary_all_002.json';row['raw']='evidence/boundary_all_002.log';row['source_digest']=current['digest']
 if row['id']=='IVA-CAVER-20':row['additional_evidence']=['evidence/PC_SUMMARY.json','evidence/R05_SUMMARY.json','evidence/finite_workload_002.log']
 if row['id'] in ['IVA-CAVER-18','IVA-CAVER-21']:row['additional_evidence']=['evidence/CLI_SUMMARY.json','evidence/CLI_AGGREGATE_SUMMARY.json','evidence/VALIDATION_CURRENTNESS.json']
for row in coverage['acceptances']:row['status']='self-validation complete via mapped IVA; independent audit not performed'
(H/'COVERAGE.json').write_text(json.dumps(coverage,ensure_ascii=False,indent=2)+'\n')
counts={n:json.loads((E/(n+'.json')).read_text())['test_passed'] for n in ['boundary_all_002','boundary_feature_002']}
with (H/'EXPERIMENTS.md').open('a') as f:f.write(f"\n\n최종 경계 검증: {counts}; boundary clippy/list/fmt exit0. Source {current['digest']}. `VALIDATION_CURRENTNESS.json`은 실제 관련 byte 비교와 재사용 범위를 기록한다. 전체31 acceptance/21 IVA/10 dimensions mapping은 COVERAGE.json. 독립 감사는 미수행.\n")
with (H/'PLAN.md').open('a') as f:f.write('\n\n## R06 경계 종료\n\nR06 GEX-10 구현·자체 검증 종료. REVIEW_HANDOFF.md/COVERAGE.json과 target/r06_boundary_001/MANIFEST.json이 경계 target. GEX-20은 미수행이며 C07도 후속 감사 범위에 포함. 연속 사용자 요청에 따라 R07 GOAL-CAFCP-01로 진행하고 이 경계에서 작업 종료하지 않는다.\n')
(H/'REVIEW_HANDOFF.md').write_text(f'''# R06 구현 경계 인계 — R07 연속 실행\n\nR06 구현·자체 검증 종료 / 독립 감사 미수행. C07의 이전 독립 미검토도 유지하며 GEX20/30 PASS를 선언하지 않는다. 사용자 연속 요청에 따라 R07을 바로 이어간다.\n\n## Target\n\n- Current source digest: `{current['digest']}`\n- 경계 manifest: [target/r06_boundary_001/MANIFEST.json](target/r06_boundary_001/MANIFEST.json)\n- Baseline: C07 manifest SHA41b98656a421e489a04d528d2dbc9ac196ff247ab8f56ec69d30cfbea4d7a882의347개 source에서 필요한 data/tool/config를 확장한 baseline/MANIFEST.json. 이전 dirty 변경의 저작권·책임을 이번 실행으로 옮기지 않는다.\n- 동결 script가 실제 membership/bytes와 격리된 forward/reverse patch 복원을 검증한다. 최종 SHA는 target/외부 locator에서 읽는다.\n\n## 완료 범위와 근거\n\nC07-OBS01은 빈 만료에서 native pending delivery 정리 후 cast settlement를 마친다. damage/result/gate를 조작하지 않는다. C08–C14는 source/identity/lifecycle/query/rollback/한도/정확 i128/trace 독립을 실제 시험으로 확인했다. C03-OBS01/C15는 i32 MIN checked RON decode와 공개 capability를 연결했다. Stat·exact 장비 사본 강화·AttackSpeedPoints·SpellPower·fingerprint·raw old V7와 nonzero fresh-process 저장, 공개 3 delivery×literal/Snapshot/Live runtime 및 실제 CLI 집계까지 검증했다.\n\n[31 acceptance·21 IVA·10 dimensions](COVERAGE.json), [실행/currentness](evidence/VALIDATION_CURRENTNESS.json), [전체 실패·교정 기록](EXPERIMENTS.md)을 따른다. 기본 전체 {counts['boundary_all_002']} passed, feature 전체 {counts['boundary_feature_002']} passed. check/event feature/release/clippy/fmt 성공. 새 finite workload1/8/32casts의 관측 on/off 결과 동일, latest amount4355 bytes 일정.\n\nPC36은576rows/36conditions/31success/5typed refusals이며 gameplay/completion/error code 차이0. R05 raw exit101을 보존하고 concurrent peak9,094,621(cap9,030,188), 초과64,433만 경고로 분류했다. 다른 hard guard 실패 없음. 측정 sample과 receipt는 evidence에 보존했다.\n\nCLI 초기 request enum/compiled graph 종류, negative exit/status 기대, 잘못된 fixture occurrence 선택과 PC isolate fixture 누락 실패를 숨기지 않았다. 교정 후 성공 원자료와 원래 실패를 모두 동결한다. repository formatter도 actual exit0.\n\n## 재량 결정과 남은 경계\n\n정책/기술 판단은 EXPERIMENT_NOTES.md를 따른다. Amount unsupported context는 명시 거부, source없는 과거 committed record는 immutable capsule로 조회, SpellPower weight는 미승인 기존값 유지, raw V7 bytes는 원본 checksum 그대로 유지했다. R07 사본/개화/일반 강화 제거는 별도 Topic의 DR과 Goal이 소유하며 R06에 구현했다고 표시하지 않는다.\n\n남은 독립 감사는 C07 포함 전체 R06 및 이후 최종 R06→R07 영향. 구현 hard blocker 없음. R07 [정식 인계](../../../../../content_authoring_fragment_copies/PLAN_HANDOFF.ko.md)와 그 실행 baseline이 다음 책임을 소유한다. R06 source 변경이 필요하면 이 target을 수정하지 않고 최종 통합 target에서 재검증한다.\n''')
road=ROOT/'core_enhanced/docs/roadmaps/content_authoring/ROADMAP_STATUS.md';s=road.read_text();s=s.replace('v1.117','v1.118',1).replace('현재 개발 주작업: **R06**,','현재 개발 주작업: **R07 준비·인수**,',1)
a=s.index('연속 실행 GEX-00');b=s.index('\n\n| 항목',a)
s=s[:a]+'''R06 구현·자체 검증을 마치고 [R06 경계 인계](../../goals/content_authoring_value_expressions_reassessment/execution/single_goal/continuations/r06_completion_001/REVIEW_HANDOFF.md)를 보존했다. 기본/feature 전체1577개, 공개 CLI·PC36·R05 검증 근거를 동결하며 독립 감사는 미수행이다. 사용자 연속 요청에 따라 [R07 정식 계획 인계](../../goals/content_authoring_fragment_copies/PLAN_HANDOFF.ko.md)와 [실행 계획](../../goals/content_authoring_fragment_copies/execution/single_goal/PLAN.md)으로 이어간다. R07 구현·최종 통합 검증은 진행 전이며 아래 C07 표는 과거 인계 이력이다.''' +s[b:];road.write_text(s)
subprocess.run([sys.executable,str(H/'freeze.py'),'r06_boundary_001'],check=True)
